struct EpisodeScreen: View {
    let episode: Episode
    let loader = SummaryLoader()
    @State private var summary: String?
    var body: some View {
        VStack {
            Text(summary ?? "Загрузка…")
            NavigationLink("Комментарии") { Text("Комментарии") }
        }
        .task {
            if summary != nil { return }
            let id = episode.id
            guard let text = try? await loader.summary(for: id) else {
                return
            }
            summary = text
        }
    }
}

`.task` сам отменяет задачу, когда экран исчезает: отменённый `Task.sleep` бросает ошибку, `try?` даёт `nil`, и `guard` выходит, ничего не записав. Появления после возврата из комментариев повторяются, но проверка `summary != nil` не даёт загрузить готовое описание второй раз.

