struct SearchService {
    func find(_ query: String) async throws -> [Episode] {
        let slow = query.count < 3
        try await Task.sleep(for: .seconds(slow ? 2 : 1))
        return [Episode(id: query.count, title: "Найдено: \(query)")]
    }
}
struct SearchScreen: View {
    let service = SearchService()
    @State private var query = ""
    @State private var results: [Episode] = []
    var body: some View {
        List {
            TextField("Поиск", text: $query)
            ForEach(results) { Text($0.title) }
        }
        .task(id: query) {
            guard let found = try? await service.find(query) else {
                return
            }
            results = found
        }
    }
}

`.task(id: query)` перезапускается при каждой новой букве и отменяет предыдущую задачу: запрос «sw» обрывается во сне, `try?` даёт `nil`, `guard` выходит и не трогает `results`. До экрана доходит только ответ на последний текст. Отдельный `onChange` больше не нужен: `.task(id:)` и запускается при появлении, и следит за значением.

